import{_ as r,c as o,j as t,a as d,G as n,a8 as s,B as m,o as l}from"./chunks/framework.BDnHobkS.js";const c=JSON.parse('{"title":"Standard Modes Protocol (MAVLink)","description":"","frontmatter":{},"headers":[],"relativePath":"en/mavlink/standard_modes.md","filePath":"en/mavlink/standard_modes.md"}'),_={name:"en/mavlink/standard_modes.md"};function i(h,e,A,D,M,f){const a=m("Badge");return l(),o("div",null,[e[0]||(e[0]=t("h1",{id:"standard-modes-protocol-mavlink",tabindex:"-1"},[d("Standard Modes Protocol (MAVLink) "),t("a",{class:"header-anchor",href:"#standard-modes-protocol-mavlink","aria-label":'Permalink to "Standard Modes Protocol (MAVLink)"'},"​")],-1)),n(a,{type:"tip",text:"PX4 v1.15"}),e[1]||(e[1]=s('<p>PX4 implements the MAVLink <a href="https://mavlink.io/en/services/standard_modes.md" target="_blank" rel="noreferrer">Standard Modes Protocol</a> from PX4 v1.15, with a corresponding implementation in QGroundControl Daily builds (and future release builds).</p><p>The protocol allows you to discover all flight modes available to the vehicle, including PX4 External modes created using the <a href="./../ros2/px4_ros2_control_interface.html">PX4 ROS 2 Control Interface</a>, and get or set the current mode.</p><h2 id="messages-command-overview" tabindex="-1">Messages &amp; Command Overview <a class="header-anchor" href="#messages-command-overview" aria-label="Permalink to &quot;Messages &amp; Command Overview&quot;">​</a></h2><p><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE" target="_blank" rel="noreferrer">Standard modes</a> are those that are common to most flight stacks with broadly the same behaviour, whereas custom modes are flight-stack specific.</p><p>This protocol allows:</p><ul><li>Discovery of all modes supported by a system from both PX4 and ROS 2 (<a href="https://mavlink.io/en/messages/common.html#MAV_CMD_REQUEST_MESSAGE" target="_blank" rel="noreferrer">MAV_CMD_REQUEST_MESSAGE</a> and <a href="https://mavlink.io/en/messages/common.html#AVAILABLE_MODES" target="_blank" rel="noreferrer">AVAILABLE_MODES</a>).</li><li>Discovery of the current mode (<a href="https://mavlink.io/en/messages/common.html#CURRENT_MODE" target="_blank" rel="noreferrer">CURRENT_MODE</a>).</li><li>Setting of standard modes (<a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE" target="_blank" rel="noreferrer">MAV_STANDARD_MODE</a>) using <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_STANDARD_MODE" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_STANDARD_MODE</a> (recommended).</li><li>Notification when the set of modes changes (<a href="https://mavlink.io/en/messages/common.html#AVAILABLE_MODES_MONITOR" target="_blank" rel="noreferrer">AVAILABLE_MODES_MONITOR</a>)</li></ul><p>You can also set custom modes using <a href="https://mavlink.io/en/messages/common.html#SET_MODE" target="_blank" rel="noreferrer">SET_MODE</a> and custom mode information from <code>AVAILABLE_MODES</code>. At time of writing <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_MODE" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_MODE</a> is not supported.</p><h2 id="supported-standard-modes" tabindex="-1">Supported Standard Modes <a class="header-anchor" href="#supported-standard-modes" aria-label="Permalink to &quot;Supported Standard Modes&quot;">​</a></h2><p>PX4 advertises support for the following standard flight modes, which means that you can start them by calling <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_STANDARD_MODE" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_STANDARD_MODE</a> with the appropriate <a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE" target="_blank" rel="noreferrer">MAV_STANDARD_MODE</a> enum value.</p><h3 id="multicopter-standard-modes" tabindex="-1">Multicopter Standard Modes <a class="header-anchor" href="#multicopter-standard-modes" aria-label="Permalink to &quot;Multicopter Standard Modes&quot;">​</a></h3><p>MC vehicles support the following standard modes (some of these are supported by all vehicles):</p><table tabindex="0"><thead><tr><th>Standard Mode</th><th>PX4 Mode</th><th>Internal Mode</th></tr></thead><tbody><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_POSITION_HOLD" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_POSITION_HOLD</a></td><td><a href="./../flight_modes_mc/position.html">MC Position mode</a></td><td>POSCTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_ALTITUDE_HOLD" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_ALTITUDE_HOLD</a></td><td><a href="./../flight_modes_mc/altitude.html">MC Altitude mode</a></td><td>ALTCTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_ORBIT" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_ORBIT</a></td><td><a href="./../flight_modes_mc/orbit.html">FW Orbit mode</a></td><td>POSCTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_SAFE_RECOVERY" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_SAFE_RECOVERY</a></td><td><a href="./../flight_modes/return.html">Return mode</a></td><td>AUTO_RTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_MISSION" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_MISSION</a></td><td><a href="./../flight_modes_mc/mission.html">Mission mode</a></td><td>AUTO_MISSION</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_LAND" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_LAND</a></td><td><a href="./../flight_modes_mc/land.html">Land mode</a></td><td>AUTO_LAND</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_TAKEOFF" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_TAKEOFF</a></td><td><a href="./../flight_modes_mc/takeoff.html">Takeoff mode</a></td><td>AUTO_TAKEOFF</td></tr></tbody></table><h3 id="fixed-wing-standard-modes" tabindex="-1">Fixed Wing Standard Modes <a class="header-anchor" href="#fixed-wing-standard-modes" aria-label="Permalink to &quot;Fixed Wing Standard Modes&quot;">​</a></h3><p>FW vehicles support the following standard modes (some of these are supported by all vehicles):</p><table tabindex="0"><thead><tr><th>Standard Mode</th><th>PX4 Mode</th><th>Internal Mode</th></tr></thead><tbody><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_CRUISE" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_CRUISE</a></td><td><a href="./../flight_modes_fw/position.html">FW Position mode</a></td><td>POSCTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_ALTITUDE_HOLD" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_ALTITUDE_HOLD</a></td><td><a href="./../flight_modes_fw/altitude.html">FW Altitude mode</a></td><td>ALTCTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_ORBIT" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_ORBIT</a></td><td><a href="./../flight_modes_fw/hold.html">FW Hold mode</a></td><td>AUTO_LOITER</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_SAFE_RECOVERY" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_SAFE_RECOVERY</a></td><td><a href="./../flight_modes/return.html">Return mode</a></td><td>AUTO_RTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_MISSION" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_MISSION</a></td><td><a href="./../flight_modes_fw/mission.html">Mission mode</a></td><td>AUTO_MISSION</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_LAND" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_LAND</a></td><td><a href="./../flight_modes_fw/land.html">Land mode</a></td><td>AUTO_LAND</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_TAKEOFF" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_TAKEOFF</a></td><td><a href="./../flight_modes_fw/takeoff.html">Takeoff mode</a></td><td>AUTO_TAKEOFF</td></tr></tbody></table><h3 id="vtol-standard-modes" tabindex="-1">VTOL Standard Modes <a class="header-anchor" href="#vtol-standard-modes" aria-label="Permalink to &quot;VTOL Standard Modes&quot;">​</a></h3><p>VTOL vehicles support the following standard modes (some of these are supported by all vehicles). Note that the behaviour of the vehicle depends on whether it is flying as a multicopter or a fixed-wing vehicle.</p><table tabindex="0"><thead><tr><th>Standard Mode</th><th>PX4 Mode</th><th>Internal Mode</th></tr></thead><tbody><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_ALTITUDE_HOLD" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_ALTITUDE_HOLD</a></td><td><a href="./../flight_modes_fw/altitude.html">FW Altitude mode</a></td><td>ALTCTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_SAFE_RECOVERY" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_SAFE_RECOVERY</a></td><td><a href="./../flight_modes/return.html">Return mode</a></td><td>AUTO_RTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_MISSION" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_MISSION</a></td><td><a href="./../flight_modes_mc/mission.html">Mission mode</a></td><td>AUTO_MISSION</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_LAND" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_LAND</a></td><td><a href="./../flight_modes_mc/land.html">Land mode</a></td><td>AUTO_LAND</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_TAKEOFF" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_TAKEOFF</a></td><td><a href="./../flight_modes_mc/takeoff.html">Takeoff mode</a></td><td>AUTO_TAKEOFF</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Note that VTOL vehicles could also support <code>MAV_STANDARD_MODE_CRUISE</code> (FW) or <code>MAV_STANDARD_MODE_POSITION_HOLD</code> (MC) and <code>MAV_STANDARD_MODE_ORBIT</code> in respective modes, but this has not been implemented.</p></div><h3 id="all-vehicles-modes" tabindex="-1">All Vehicles Modes <a class="header-anchor" href="#all-vehicles-modes" aria-label="Permalink to &quot;All Vehicles Modes&quot;">​</a></h3><p>These standard modes are mapped for all vehicle types.</p><table tabindex="0"><thead><tr><th>Standard Mode</th><th>PX4 Mode</th><th>Internal Mode</th></tr></thead><tbody><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_SAFE_RECOVERY" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_SAFE_RECOVERY</a></td><td><a href="./../flight_modes/return.html">Return mode</a></td><td>AUTO_RTL</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_MISSION" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_MISSION</a></td><td><a href="./../flight_modes_mc/mission.html">Mission mode</a></td><td>AUTO_MISSION</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_LAND" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_LAND</a></td><td><a href="./../flight_modes_mc/land.html">Land mode</a></td><td>AUTO_LAND</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_STANDARD_MODE_TAKEOFF" target="_blank" rel="noreferrer">MAV_STANDARD_MODE_TAKEOFF</a></td><td><a href="./../flight_modes_mc/takeoff.html">Takeoff mode</a></td><td>AUTO_TAKEOFF</td></tr></tbody></table><h2 id="standard-mode-implementation" tabindex="-1">Standard Mode Implementation <a class="header-anchor" href="#standard-mode-implementation" aria-label="Permalink to &quot;Standard Mode Implementation&quot;">​</a></h2><p>PX4 presents its own custom modes as standard modes, when appropriate.</p><p>When implementing a mapping to a standard mode, see <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/lib/modes/standard_modes.hpp" target="_blank" rel="noreferrer">src/lib/modes/standard_modes.hpp</a>, and in particular the implementation of <code>getNavStateFromStandardMode()</code>.</p><p>Note that PX4 External modes created using the <a href="./../ros2/px4_ros2_control_interface.html">PX4 ROS 2 Control Interface</a> are also exposed by this interface.</p><h2 id="other-mavlink-mode-changing-commands" tabindex="-1">Other MAVLink Mode-changing Commands <a class="header-anchor" href="#other-mavlink-mode-changing-commands" aria-label="Permalink to &quot;Other MAVLink Mode-changing Commands&quot;">​</a></h2><p>Some modes, both standard and custom, can also be set using specific commands and messages. This can be more convenient that just starting the mode, in particular when the message allows additional settings to be configured.</p><p>PX4 supports these commands for changing modes on some vehicle types:</p><ul><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_TAKEOFF" target="_blank" rel="noreferrer">MAV_CMD_NAV_TAKEOFF</a> — Takeoff mode</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_RETURN_TO_LAUNCH" target="_blank" rel="noreferrer">MAV_CMD_NAV_RETURN_TO_LAUNCH</a> — Return mode</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LAND" target="_blank" rel="noreferrer">MAV_CMD_NAV_LAND</a> — Land mode</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FOLLOW" target="_blank" rel="noreferrer">MAV_CMD_DO_FOLLOW</a> — MC Follow mode</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FOLLOW_REPOSITION" target="_blank" rel="noreferrer">MAV_CMD_DO_FOLLOW_REPOSITION</a> — Follow mode (from new position)</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_ORBIT" target="_blank" rel="noreferrer">MAV_CMD_DO_ORBIT</a> — MC Orbit mode</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_VTOL_TAKEOFF" target="_blank" rel="noreferrer">MAV_CMD_NAV_VTOL_TAKEOFF</a> — VTOL specific takeoff mode</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_REPOSITION" target="_blank" rel="noreferrer">MAV_CMD_DO_REPOSITION</a></li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_PAUSE_CONTINUE" target="_blank" rel="noreferrer">MAV_CMD_DO_PAUSE_CONTINUE</a> — Pauses a mission by putting the vehicle into Hold/Loiter</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_MISSION_START" target="_blank" rel="noreferrer">MAV_CMD_MISSION_START</a> — Starts a mission.</li></ul><p>Note that these commands predate &quot;standard modes&quot; and are mapped to vehicle-specific custom modes. What that means is that even though the standard mode may be applicable to multiple vehicle types, the mode may only work for particular vehicles. For example, the Orbit standard mode maps to Orbit mode on MC and Hold/Loiter on FW: but at time of writing the <code>MAV_CMD_DO_ORBIT</code> would start orbit mode in MC and be ignored on FW.</p>',31))])}const p=r(_,[["render",i]]);export{c as __pageData,p as default};
